codeExamples.code:
resource "aws_glue_catalog_database" "analytics" {
  name = "analytics"
}

resource "aws_glue_crawler" "orders_crawler" {
  name          = "orders-crawler"
  role          = aws_iam_role.glue_role.arn
  database_name = aws_glue_catalog_database.analytics.name
  schedule      = "cron(0 2 * * ? *)"  # daily at 02:00 UTC

  s3_target {
    path = "s3://my-data-lake/raw/orders/"
  }

  schema_change_policy {
    update_behavior = "UPDATE_IN_DATABASE"
    delete_behavior = "LOG"
  }
}

query getDownstreamLineage {
  searchAcrossLineage(
    input: {
      urn: "urn:li:dataset:(urn:li:dataPlatform:snowflake,analytics.staging.orders,PROD)"
      direction: DOWNSTREAM
      types: [DATASET, DASHBOARD, CHART]
      count: 100
    }
  ) {
    searchResults {
      degree
      entity {
        urn
        type
      }
    }
  }
}
